CREATE   VIEW [RegsBI].[vwSurveyAnswer_CE]
AS
SELECT 
	[ricsv1_surveyanswerId] AS [rics_surveyanswerid],
	[ricsv1_SurveyResponse] AS [rics_surveyresponse], 
	[ricsv1_Survey] AS [rics_survey],
	[statuscode], 
	[StatusCode_Description],
	[statecode],
	[StateCode_Description],
	[ricsv1_score] AS [rics_score],
	[overriddencreatedon], 
	[ricsv1_Question] AS [rics_question],
	[ricsv1_QuestionName] AS [rics_questionName],
	[rics_possibleanswerconfig], 
	[ricsv1_PossibleAnswer] AS [rics_possibleanswer],
	[ricsv1_PossibleAnswerName],
	[rics_questionsetconfig], 
	[ricsv1_QuestionSet] AS [rics_questionset],
	[ricsv1_QuestionSetName],
	[owningbusinessunit], 
	[OwnerIdName],
	[ricsv1_Order] AS [rics_order],
	[ricsv1_name] AS [rics_name],
	[Modified_On] AS [modifiedon],
	[ModifiedByName],
	[ricsv1_Heading] AS [rics_heading],
	[ricsv1_HeadingName],
	[rics_evidencepath],
	[rics_evidencefilename], 
	[Created_On] AS [createdon],
	[CreatedByName],
	[ricsv1_answerstatus] AS [rics_answerstatus], 
	[ricsv1_Answer] AS [rics_answer], 
	[ricsv1_AdditionalInformation] AS [rics_additionalinformation],
	[rics_questiontext]
FROM [synapse_ce].[vwricsv1_surveyanswer]
